def process(loadBoston, loadChatham, loadAmherst, loadAshburnham) -> pd.DataFrame:
    import pandas as pd

    def one(df: pd.DataFrame, region: str) -> pd.DataFrame:
        d = df.copy()
        # keep only year rows that are numeric
        d['Year_num'] = pd.to_numeric(d['Year'], errors='coerce')
        d = d[d['Year_num'].notna()].copy()
        d['Year_num'] = d['Year_num'].astype(int)
        d = d[d['Year_num'] == 2020].copy()
        if d.empty:
            return pd.DataFrame([{'region': region, 'Jun': pd.NA, 'Jul': pd.NA, 'Aug': pd.NA, 'jjaTotal': pd.NA}])

        for c in ['Jun', 'Jul', 'Aug']:
            d[c] = pd.to_numeric(d[c].replace({'M': pd.NA, 'T': 0}), errors='coerce')

        out = pd.DataFrame([{
            'region': region,
            'Jun': float(d['Jun'].iloc[0]) if pd.notna(d['Jun'].iloc[0]) else pd.NA,
            'Jul': float(d['Jul'].iloc[0]) if pd.notna(d['Jul'].iloc[0]) else pd.NA,
            'Aug': float(d['Aug'].iloc[0]) if pd.notna(d['Aug'].iloc[0]) else pd.NA,
        }])
        out['jjaTotal'] = out[['Jun', 'Jul', 'Aug']].sum(axis=1, skipna=False)
        return out

    res = pd.concat([
        one(loadBoston, 'Boston'),
        one(loadChatham, 'Chatham'),
        one(loadAmherst, 'Amherst'),
        one(loadAshburnham, 'Ashburnham'),
    ], ignore_index=True)

    # rank only where total is present
    res['rank'] = res['jjaTotal'].rank(method='min', ascending=False)
    return res.sort_values(['rank', 'region']).reset_index(drop=True)
